// The flake-or-regression skill's runner (.claude/skills/flake-or-regression/SKILL.md).
// Reruns the two-browser test K times on main and K times on the branch, alternating, and counts
// how often each side hits the failure's signature. The decision rule is in scripts/flake-lib.mjs.
//
//   node scripts/flake-or-regression.mjs --main <ref> --branch <ref> --signature "<text>" [--k 10] [--mode direct|relay] --out <empty dir>
//
// Exit: 0 a verdict (already flaky, branch broke it, made worse), 3 inconclusive, 2 couldn't run.
// Writes <out>/runs.csv, <out>/verdict.md and each run's output.
import { spawnSync, execFileSync } from 'node:child_process';
import { existsSync, readdirSync, mkdirSync, writeFileSync, rmSync, symlinkSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { classify, firstFailure, decide, order, MAX_K } from './flake-lib.mjs';

const arg = (k, d) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
const OUT = arg('--out'), SIG = arg('--signature'), MAIN = arg('--main'), BRANCH = arg('--branch'), MODE = arg('--mode', 'direct'), K = Number(arg('--k', '10'));
const stop = (why) => { console.log(`STOP: ${why}`); process.exit(2); };
if (!OUT) stop('no --out folder given');
if (existsSync(OUT) && readdirSync(OUT).length) stop(`the evidence folder ${OUT} isn't empty`);
if (!SIG) stop('no --signature: name the failure (a line of its output, for example "timed out after 90 s at two-browser.mjs:229")');
if (!MAIN || !BRANCH) stop('give both --main and --branch');
if (!Number.isInteger(K) || K < 3 || K > MAX_K) stop(`--k must be 3 to ${MAX_K}`);
if (!['direct', 'relay'].includes(MODE)) stop('--mode must be direct or relay');
mkdirSync(OUT, { recursive: true });
const repo = resolve('.'), git = (...a) => execFileSync('git', a, { cwd: repo, encoding: 'utf8' }).trim();
const sha = (ref) => { try { return git('rev-parse', '--verify', `${ref}^{commit}`); } catch { stop(`${ref} isn't a commit here (git fetch it first)`); } };
const sides = { main: { ref: MAIN, sha: sha(MAIN) }, branch: { ref: BRANCH, sha: sha(BRANCH) } };
for (const [name, s] of Object.entries(sides)) {
  s.dir = `/tmp/for-${name}-${s.sha.slice(0, 7)}`;
  rmSync(s.dir, { recursive: true, force: true }); git('worktree', 'prune');
  git('worktree', 'add', '--detach', s.dir, s.sha);
  symlinkSync(join(repo, 'node_modules'), join(s.dir, 'node_modules'));
  if (!existsSync(join(s.dir, 'tests', 'two-browser.mjs'))) stop(`${name} (${s.sha.slice(0, 7)}) has no tests/two-browser.mjs`);
  s.counts = { hit: 0, pass: 0, other: 0, error: 0 }; s.firstHit = null; s.firstOther = null;
}
const rows = ['run,side,commit,outcome,seconds,first_failure'];
for (const [i, name] of order(K).entries()) {
  const s = sides[name], t0 = Date.now();
  const r = spawnSync('node', ['tests/two-browser.mjs', ...(MODE === 'relay' ? ['--relay'] : [])], { cwd: s.dir, encoding: 'utf8', timeout: 10 * 60000 });
  const out = (r.stdout || '') + (r.stderr || ''), secs = Math.round((Date.now() - t0) / 1000);
  const outcome = r.error?.code === 'ETIMEDOUT' ? 'other' : classify(r.status, out, SIG);
  s.counts[outcome]++;
  const file = `run-${String(i + 1).padStart(2, '0')}-${name}.txt`;
  writeFileSync(join(OUT, file), out.replaceAll(repo, '<repo>').replaceAll(s.dir, '<worktree>'));
  if (outcome === 'hit' && !s.firstHit) s.firstHit = file;
  if (outcome === 'other' && !s.firstOther) s.firstOther = file;
  rows.push([i + 1, name, s.sha.slice(0, 7), outcome, secs, JSON.stringify(firstFailure(out))].join(','));
  console.log(`run ${i + 1}/${2 * K} ${name.padEnd(6)} ${outcome.padEnd(5)} ${secs} s ${firstFailure(out).slice(0, 90)}`);
  if (outcome === 'error' && s.counts.error >= 2) { writeFileSync(join(OUT, 'runs.csv'), rows.join('\n') + '\n'); stop(`the test couldn't run twice on ${name} (see ${file}): fix the setup, not the verdict`); }
}
writeFileSync(join(OUT, 'runs.csv'), rows.join('\n') + '\n');
const d = decide({ k: K, main: sides.main.counts, branch: sides.branch.counts });
const md = `# flake-or-regression: ${d.verdict}

- Signature: \`${SIG}\`
- Mode: ${MODE}, K = ${K} runs per side, alternating (main first)
- main: \`${sides.main.ref}\` = ${sides.main.sha.slice(0, 7)} · hit ${sides.main.counts.hit}, pass ${sides.main.counts.pass}, other failure ${sides.main.counts.other}, couldn't run ${sides.main.counts.error}${sides.main.firstHit ? ` · first hit: ${sides.main.firstHit}` : ''}
- branch: \`${sides.branch.ref}\` = ${sides.branch.sha.slice(0, 7)} · hit ${sides.branch.counts.hit}, pass ${sides.branch.counts.pass}, other failure ${sides.branch.counts.other}, couldn't run ${sides.branch.counts.error}${sides.branch.firstHit ? ` · first hit: ${sides.branch.firstHit}` : ''}

**Verdict: ${d.verdict}.** ${d.why}.

The rule (scripts/flake-lib.mjs, fixed before any run): already flaky if main hit it at least once and the branch no more than twice as often; the branch broke it if main never did and the branch did at least 3 times; made worse if both did and the branch at least 3 times as often; anything else is inconclusive.
${sides.branch.counts.other + sides.main.counts.other ? `\nOther failures (not this signature) were seen: main ${sides.main.counts.other}, branch ${sides.branch.counts.other}. Read them: they may be a different problem.${sides.branch.firstOther ? ` First on the branch: ${sides.branch.firstOther}.` : ''}${sides.main.firstOther ? ` First on main: ${sides.main.firstOther}.` : ''}\n` : ''}`;
writeFileSync(join(OUT, 'verdict.md'), md);
console.log(md);
for (const s of Object.values(sides)) { try { git('worktree', 'remove', '--force', s.dir); } catch {} }
process.exit(d.verdict === 'inconclusive' ? 3 : 0);

// Pure helpers for scripts/flake-or-regression.mjs (the flake-or-regression skill), unit tested
// in tests/flake-lib.test.mjs. The decision rule is fixed here, before any run, and never tuned to
// a result.

export const MAX_K = 30;

// One run's outcome from its exit code and output: "hit" if the output has the failure's signature
// (whatever else happened), "other" for any other failure, "error" if the test couldn't start or
// run (the browser or the server), "pass" otherwise.
export function classify(exit, output, signature) {
  const out = String(output || '');
  if (signature && out.includes(signature)) return 'hit';
  if (/Executable doesn't exist|EADDRINUSE|Cannot find module|browserType\.launch|ERR_MODULE_NOT_FOUND/.test(out)) return 'error';
  if (exit === 0) return 'pass';
  return 'other';
}

// The first line that says what failed: a FAIL line or a timeout, for the run table.
export const firstFailure = (output) => (String(output || '').split('\n').find((l) => /^FAIL |timed out after|Error:/.test(l)) || '').slice(0, 200);

// The rule, from how often each side hit the signature in K runs each:
//   already flaky   main hit at least once, and the branch's rate is no more than double main's
//   branch broke it main never hit, the branch hit at least 3 times
//   made worse      both hit, and the branch's rate is at least 3 times main's
//   inconclusive    anything else, including neither side hitting it: stop and report, don't guess
// Runs that errored don't count as either; with fewer than K usable runs on a side it's inconclusive.
export function decide({ k, main, branch }) {
  const usable = (s) => s.hit + s.pass + s.other;
  if (usable(main) !== k || usable(branch) !== k) return { verdict: 'inconclusive', why: `fewer than ${k} usable runs on a side (main ${usable(main)}, branch ${usable(branch)})` };
  // both sides have K usable runs, so rates compare as whole counts (no floating point)
  if (main.hit >= 1 && branch.hit <= 2 * main.hit) return { verdict: 'already flaky', why: `main hit it ${main.hit} of ${k}, the branch ${branch.hit} of ${k} (no more than double)` };
  if (main.hit === 0 && branch.hit >= 3) return { verdict: 'branch broke it', why: `main never hit it in ${k} runs, the branch hit it ${branch.hit} of ${k}` };
  if (main.hit >= 1 && branch.hit >= 3 * main.hit) return { verdict: 'made worse', why: `main hit it ${main.hit} of ${k}, the branch ${branch.hit} of ${k} (at least 3 times as often)` };
  return { verdict: 'inconclusive', why: `main hit it ${main.hit} of ${k}, the branch ${branch.hit} of ${k}: the rule doesn't decide this` };
}

// The order of runs: alternate main and branch, so the machine's load falls on both evenly.
export const order = (k) => Array.from({ length: 2 * k }, (_, i) => (i % 2 ? 'branch' : 'main'));
